def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in into s_out."""
    # Simple implementation for now
    # Look for longest common prefix and suffix
    prefix_len = 0
    while prefix_len < len(s_in) and prefix_len < len(s_out) and s_in[prefix_len] == s_out[prefix_len]:
        prefix_len += 1

    suffix_len = 0
    while (suffix_len < len(s_in) - prefix_len and 
           suffix_len < len(s_out) - prefix_len and
           s_in[-(suffix_len + 1)] == s_out[-(suffix_len + 1)]):
        suffix_len += 1

    # What's left in the middle
